import{WidgetStatusType}from"./WidgetContracts";export class WidgetStatusHelper{static Success(e){return Promise.resolve({state:e,statusType:WidgetStatusType.Success})}static Failure(e,t=!0,i=!1){return Promise.reject({message:e,isRichText:i,isUserVisible:t})}static Unconfigured(){return Promise.resolve({statusType:WidgetStatusType.Unconfigured})}};export class WidgetConfigurationSave{static Valid(e){return Promise.resolve({customSettings:e,isValid:!0})}static Invalid(){return Promise.reject({isValid:!1})}};export class WidgetSizeConverter{static CalculatePixelSize(e,t,i){return t*e+i*(e-1)}static GetWidgetWidth(){return WidgetSizeConverter.CellWidth}static GetWidgetHeight(){return WidgetSizeConverter.CellHeight}static GetWidgetMarginWidth(){return WidgetSizeConverter.CellMarginWidth}static GetWidgetMarginHeight(){return WidgetSizeConverter.CellMarginHeight}static ColumnsToPixelWidth(e){return this.CalculatePixelSize(e,WidgetSizeConverter.GetWidgetWidth(),WidgetSizeConverter.GetWidgetMarginWidth())}static RowsToPixelHeight(e){return this.CalculatePixelSize(e,WidgetSizeConverter.GetWidgetHeight(),WidgetSizeConverter.GetWidgetMarginHeight())}};WidgetSizeConverter.CellWidth=160,WidgetSizeConverter.CellHeight=160,WidgetSizeConverter.CellMarginWidth=10,WidgetSizeConverter.CellMarginHeight=10;